mapper.select:
select p.id, p.groupid, g.groupname, apps.id as appid, apps.appname, apps.icon, apps.loginurl, apps.protocol, apps.category, apps.description, apps.vendor, apps.vendorurl from mxk_apps apps join mxk_access p on p.appid = apps.id and p.instid = #{instId} join mxk_groups g on g.id = p.groupid and g.instid = #{instId} where apps.instid = #{instId}
and p.groupid = #{groupId}
order by apps.sortindex, apps.id
